window.NurseFlowData={
 getSnapshot:()=>clone(data),
 async restoreFromCloud(raw){
  const candidate=normalize(raw);
  if(!raw||Object.keys(raw.shifts||{}).length!==Object.keys(candidate.shifts).length)throw Error('Cloud schedule validation failed');
  await backupSnapshot('before-supabase-restore');
  const before=data;data=candidate;
  if(!commit('ดึงตารางจาก Supabase แล้ว')){data=before;throw Error('Could not write local storage')}
  render();
 }
};
